    let v15 = b.konst(Width::new(64), 0xffffffffffffffff);
    let v16 = b.select(v10, v14, v15);
    st.set_reg(b, "LO", v16, Some(v8));
    st.set_reg(b, "HI", v3, Some(v8));
    let v17 = b.not(v8);
    let v18 = b.bin(BinOp::SDiv, v4, v6);
    let v19 = b.extract(v18, 0, Width::new(64));
