/// The generated template of `enc`, if there is one.
pub(crate) fn template(enc: Encoding) -> Option<GenFn> {
    Some(match enc {
        Encoding::Daddiu => Daddiu,
        Encoding::Daddu => Daddu,
        Encoding::Daddi => Daddi,
        Encoding::Dadd => Dadd,
        Encoding::Add => Add,
        Encoding::Addi => Addi,
        Encoding::Addu => Addu,
        Encoding::Addiu => Addiu,
        Encoding::Dsubu => Dsubu,
        Encoding::Dsub => Dsub,
        Encoding::Sub => Sub,
        Encoding::Subu => Subu,
        Encoding::And => And,
        Encoding::Andi => Andi,
        Encoding::Or => Or,
        Encoding::Ori => Ori,
        Encoding::Nor => Nor,
        Encoding::Xor => Xor,
        Encoding::Xori => Xori,
        Encoding::Lui => Lui,
        Encoding::Dsll => Dsll,
        Encoding::Dsll32 => Dsll32,
        Encoding::Dsllv => Dsllv,
        Encoding::Dsra => Dsra,
        Encoding::Dsra32 => Dsra32,
        Encoding::Dsrav => Dsrav,
        Encoding::Dsrl => Dsrl,
        Encoding::Dsrl32 => Dsrl32,
        Encoding::Dsrlv => Dsrlv,
        Encoding::Sll => Sll,
        Encoding::Sllv => Sllv,
        Encoding::Sra => Sra,
        Encoding::Srav => Srav,
        Encoding::Srl => Srl,
        Encoding::Srlv => Srlv,
        Encoding::Slt => Slt,
        Encoding::Slti => Slti,
        Encoding::Sltu => Sltu,
        Encoding::Sltiu => Sltiu,
        Encoding::Mfhi => Mfhi,
        Encoding::Mflo => Mflo,
        Encoding::Mthi => Mthi,
        Encoding::Mtlo => Mtlo,
        Encoding::Mult => Mult,
        Encoding::Multu => Multu,
        Encoding::Dmult => Dmult,
        Encoding::Dmultu => Dmultu,
        Encoding::Div => Div,
        Encoding::Divu => Divu,
        Encoding::Ddiv => Ddiv,
        Encoding::Ddivu => Ddivu,
        _ => return None,
    })
}
